package com.xuhang.mealops.inventory.infrastructure.persistence;
import java.math.BigDecimal; import java.util.*; import org.springframework.stereotype.Repository; import com.xuhang.mealops.inventory.application.InventoryTransactionRepository; import com.xuhang.mealops.inventory.domain.InventoryConsumptionAllocation;
@Repository public class MyBatisInventoryTransactionRepository implements InventoryTransactionRepository { private final InventoryTransactionMapper mapper; public MyBatisInventoryTransactionRepository(InventoryTransactionMapper m){mapper=m;} public long createConsumption(long ingredientId,BigDecimal amount,String unit,List<InventoryConsumptionAllocation> xs){var h=new HashMap<String,Object>();h.put("ingredientId",ingredientId);h.put("amount",amount);h.put("unit",unit);mapper.insertHeader(h); long id=((Number)h.get("id")).longValue(); for(var x:xs){var a=new HashMap<String,Object>();a.put("transactionId",id);a.put("position",x.position());a.put("batchId",x.batchId());a.put("amount",x.amount());a.put("before",x.before());a.put("after",x.after());mapper.insertAllocation(a);} return id;} }
